1	import { spawn, ChildProcess } from "node:child_process";
2	import * as path from "node:path";
3	import * as fs from "node:fs";
4	import * as os from "node:os";
5	import { pathToFileURL, fileURLToPath } from "node:url";
6	import { buildMcpEnvironment } from "./mcp.js";
7	
8	const LSP_MAX_BUFFER_BYTES = 16 * 1024 * 1024;
9	const EDIT_DIAGNOSTICS_GRACE_MS = 8_000;
10	const LSP_TOOLCHAIN_VARS = ["RUSTUP_HOME", "CARGO_HOME", "RUSTUP_TOOLCHAIN", "GOPATH", "GOROOT", "GOCACHE", "GOMODCACHE"];
11	/**
12	 * Documents one server keeps open; the least recently queried one beyond this is closed (`didClose`), which hands that
13	 * file back to the server's own reading of the disk. Every query re-checks every open document (one realpath and one
14	 * stat each), and a server re-analyses its open documents on each change, so the set is kept to what an agent works on
15	 * at one time (an editor's worth of tabs), not every file it ever asked about.
16	 */
17	export const MAX_OPEN_DOCUMENTS = 32;
18	/**
19	 * A file's stat is taken as proof that it has not changed only when its newest timestamp was at least this old when the
20	 * file was read. Timestamps come from a clock that advances in steps (a kernel tick, or 1 to 2 s on coarse file systems):
21	 * a second write inside the step of the first leaves them equal, so a file changed that recently is compared by content.
22	 */
23	export const STAT_SETTLE_MS = 2_000;
24	/**
25	 * Push-only servers: how long the server must have published nothing before a list that predates a change to another
26	 * document is taken as still standing (see `settledAt`). It has to outlast the gap between a server's publish for the
27	 * changed file and its publish for a dependent one; servers batch or debounce those within a few hundred milliseconds,
28	 * and 1 s is several times that. Longer would make every such query slower by as much; shorter would return more old
29	 * lists from a server that is slow to reach the dependent file. Counted from the last publish, so a query made a moment
30	 * after an edit usually finds most of it already spent.
31	 */
32	export const PUBLISH_QUIET_MS = 1_000;
33	/** A staged server's progress must have been over for this long before its lists are taken as settled. */
34	const QUIET_MS = 1500;
35	/** LSP `ServerCancelled`: the server abandoned a pull request; its data says whether to ask again. */
36	const SERVER_CANCELLED = -32802;
37	/** How often one diagnostics query asks again after such a cancellation (within its timeout). */
38	const PULL_RETRIGGER_LIMIT = 3;
39	/** Wakes a query waiting for evidence that the server has settled: any publish, the end of a progress cycle, a close. */
40	const ANY_DOCUMENT = "";
41	
42	export type DiagnosticsAnswer = { status: "ok"; diagnostics: LspDiagnostic[] } | { status: "unavailable"; reason: string };
43	
44	const toDiagnostics = (items: any[]): LspDiagnostic[] =>
45	  items.map((d: any) => ({
46	    range: d.range,
47	    severity: d.severity === 1 ? "error" : d.severity === 2 ? "warning" : "information",
48	    message: d.message,
49	    source: d.source,
50	    ...(d.code !== undefined && d.code !== null ? { code: d.code } : {}),
51	  }));
52	
53	const SYSTEM_BIN_DIRS = ["/usr/bin", "/bin", "/usr/local/bin", "/sbin", "/usr/sbin"];
54	
55	function realOrNull(p: string): string | null {
56	  try {
57	    return fs.realpathSync(p);
58	  } catch {
59	    return null;
60	  }
61	}
62	
63	/** The containment rule for documents; `child` and `root` are real paths. */
64	const outsideRoot = (root: string, child: string): boolean => {
65	  const rel = path.relative(root, child);
66	  return rel.startsWith("..") || path.isAbsolute(rel);
67	};
68	
69	const isInside = (parent: string, child: string): boolean => {
70	  const rel = path.relative(parent, child);
71	  return rel === "" || (rel !== ".." && !rel.startsWith(".." + path.sep) && !path.isAbsolute(rel));
72	};
73	
74	/**
75	 * The environment a language server starts with: the MCP allowlist (no credentials) plus the toolchain locations the
76	 * servers need. PATH keeps only existing absolute entries that do not resolve (through symlinks) into the workspace, so
77	 * project content cannot supply the binary. When the workspace is a home directory or a system prefix that itself
78	 * contains the toolchain, its entries are kept: dropping them would leave no server installed.
79	 */
80	export function buildLspEnvironment(workspace: string, source: NodeJS.ProcessEnv = process.env): Record<string, string> {
81	  const env = buildMcpEnvironment();
82	  for (const k of LSP_TOOLCHAIN_VARS) if (source[k] !== undefined) env[k] = source[k]!;
83	  for (const [k, v] of Object.entries(env)) {
84	    if (/^(https?|all)_proxy$/i.test(k) && /\/\/[^/]*@/.test(v)) delete env[k];
85	  }
86	  const root = realOrNull(path.resolve(workspace));
87	  const broad =
88	    root !== null &&
89	    [os.homedir(), ...SYSTEM_BIN_DIRS].some((d) => {
90	      const real = realOrNull(d);
91	      return real !== null && isInside(root, real);
92	    });
93	  env.PATH = (env.PATH ?? "")
94	    .split(path.delimiter)
95	    .filter((d) => {
96	      if (!path.isAbsolute(d) || root === null) return false;
97	      const real = realOrNull(d);
98	      return real !== null && (broad || !isInside(root, real));
99	    })
100	    .join(path.delimiter);
101	  return env;
102	}
103	
104	/** Thrown by a query whose file cannot be given to the server; the message is the answer the caller reports. */
105	const unreadable = (filePath: string): Error => new Error(`${filePath} is not a readable file inside the workspace.`);
106	
107	/** One spelling per path for comparisons: no trailing separator, no `.` or `..`, a lower-case drive letter. */
108	const comparablePath = (p: string): string => path.resolve(p).replace(/^[A-Z]:/, (drive) => drive.toLowerCase());
109	
110	interface FileState {
111	  text: string;
112	  /** Device, inode, size, mtime and ctime (ns). ctime is included because an edit can restore size and mtime but not it. */
113	  stamp: string;
114	  /** The stamp alone proves "unchanged" (see STAT_SETTLE_MS); otherwise the next check compares content. */
115	  settled: boolean;
116	}
117	
118	function stampOf(st: fs.BigIntStats, readAtMs: number): Pick<FileState, "stamp" | "settled"> {
119	  const newest = st.mtimeNs > st.ctimeNs ? st.mtimeNs : st.ctimeNs;
120	  return {
121	    stamp: `${st.dev}:${st.ino}:${st.size}:${st.mtimeNs}:${st.ctimeNs}`,
122	    settled: BigInt(readAtMs) * 1_000_000n - newest >= BigInt(STAT_SETTLE_MS) * 1_000_000n,
123	  };
124	}
125	
126	/**
127	 * The regular file at `real` (a path already resolved through symlinks), or null. The descriptor refuses a symlink put in
128	 * the last component since the path was resolved, and does not block on a FIFO; the stamp is of the file actually read.
129	 */
130	function readRegularFile(real: string): FileState | null {
131	  let fd: number | undefined;
132	  try {
133	    const readAtMs = Date.now();
134	    fd = fs.openSync(real, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0) | (fs.constants.O_NONBLOCK ?? 0));
135	    const st = fs.fstatSync(fd, { bigint: true });
136	    if (!st.isFile()) return null;
137	    return { text: fs.readFileSync(fd, "utf-8"), ...stampOf(st, readAtMs) };
138	  } catch {
139	    return null;
140	  } finally {
141	    if (fd !== undefined) fs.closeSync(fd);
142	  }
143	}
144	
145	/** What the server holds for one file. The client's only record of it: every query goes through `LspClient.open`. */
146	interface OpenDocument extends FileState {
147	  /** Identity: the file's real path. Two spellings of one file (a symlink, a symlinked workspace) are one document. */
148	  key: string;
149	  /** The spelling sent to the server, and the paths a server may name it by (as sent, and canonical). */
150	  uri: string;
151	  paths: string[];
152	  /** The version sent with the latest didOpen or didChange. */
153	  version: number;
154	  /** The sequence number of the latest didChange for it; 0 while it is as it was opened. */
155	  changedSeq: number;
156	  /** The latest list published for this version, and the client sequence number when it arrived. */
157	  diagnostics?: { list: LspDiagnostic[]; seq: number };
158	  /** The last full report pulled for it, kept so that an "unchanged" reply to its `resultId` has a list to stand for. */
159	  pulled?: { list: LspDiagnostic[]; resultId?: string };
160	  /** Diagnostics queries waiting on this document; it is not evicted meanwhile. */
161	  waiting: number;
162	}
163	
164	export interface LspPosition {
165	  line: number;
166	  character: number;
167	}
168	
169	export interface LspRange {
170	  start: LspPosition;
171	  end: LspPosition;
172	}
173	
174	export interface LspLocation {
175	  uri: string;
176	  range: LspRange;
177	}
178	
179	export interface LspServerSpec {
180	  cmd: string;
181	  args?: string[];
182	  languageId: string;
183	  /** Extra variables for this server only; the built-in table never sets it. */
184	  env?: Record<string, string>;
185	  /**
186	   * The server analyses in stages and publishes an empty list before it has finished (rust-analyzer: before the Cargo
187	   * project is loaded and types are analysed). Diagnostics then wait, within the caller's timeout, until the server's own
188	   * progress reports (`$/progress`) have ended, instead of returning on the first publish.
189	   */
190	  awaitProgress?: boolean;
191	}
192	
193	export interface LspDiagnostic {
194	  range: LspRange;
195	  severity: "error" | "warning" | "information" | "hint";
196	  message: string;
197	  source?: string;
198	  code?: string | number;
199	}
200	
201	/**
202	 * Lightweight Language Server Protocol Client (Candidate #44)
203	 * Communicates with rust-analyzer, typescript-language-server, pyright via JSON-RPC stdio
204	 */
205	export class LspClient {
206	  public serverCmd: string;
207	  public serverArgs: string[];
208	  public rootPath: string;
209	  /** Open documents by identity (real path), least recently queried first. */
210	  private documents: Map<string, OpenDocument> = new Map();
211	  /** The same documents by the URI sent to the server. */
212	  private opened: Map<string, OpenDocument> = new Map();
213	  /**
214	   * One counter orders everything the client tells the server about content: it supplies each document version (so a
215	   * version is never reused, also not by a document closed and opened again) and stamps each list on arrival.
216	   * `lastChangeSeq` is its value at the latest change of content the server holds: a didChange, or the close of a document
217	   * whose file is gone. A list that arrived before it was computed without that change.
218	   */
219	  private seq = 0;
220	  private lastChangeSeq = 0;
221	  /** The latest change no publish can vouch for any more: its document was closed (deleted, or evicted) before the server published for it. */
222	  private unevidencedSeq = 0;
223	  /** When the server last published diagnostics for any file, and whether it has ever attached a version. */
224	  private lastPublishAt = 0;
225	  private versionedPublishes = false;
226	  /**
227	   * Set when the server offers pull diagnostics (`diagnosticProvider`): a diagnostics query is then a
228	   * `textDocument/diagnostic` request, answered for the content the server holds, and published lists are not consulted.
229	   * `interFileDependencies` and `workspaceDiagnostics` are recorded as announced; workspace diagnostics are not used.
230	   */
231	  public diagnosticProvider: { identifier?: string; interFileDependencies: boolean; workspaceDiagnostics: boolean } | null = null;
232	  private diagnosticWaiters: Map<string, Array<() => void>> = new Map();
233	  private child: ChildProcess | null = null;
234	  private nextId: number = 1;
235	  private pending: Map<number, { resolve: (val: any) => void; reject: (err: any) => void }> = new Map();
236	  private documentChangedAt: Map<string, number> = new Map();
237	  private saveOptions?: { includeText?: boolean };
238	  private buffer: Buffer = Buffer.alloc(0);
239	  public initialized: boolean = false;
240	  /** Tokens of the server's work-done progress that has begun and not ended (with the sequence number at their begin), and when progress last changed. */
241	  private progressActive: Map<string, number> = new Map();
242	  /** The highest sequence number at which a progress cycle that has since ended began: the server finished work it started after every change up to it. */
243	  private progressSettledSeq = 0;
244	  private progressSeen = false;
245	  private lastProgressAt = 0;
246	
247	  constructor(serverCmd: string, rootPath: string, serverArgs: string[] = [], private extraEnv: Record<string, string> = {}, private awaitProgress: boolean = false) {
248	    this.serverCmd = serverCmd;
249	    this.serverArgs = serverArgs;
250	    this.rootPath = path.resolve(rootPath);
251	  }
252	
253	  public async start(): Promise<boolean> {
254	    try {
255	      this.child = spawn(this.serverCmd, this.serverArgs, {
256	        cwd: this.rootPath,
257	        env: { ...buildLspEnvironment(this.rootPath), ...this.extraEnv },
258	        stdio: ["pipe", "pipe", "pipe"],
259	      });
260	      this.child.stderr?.resume();
261	
262	      this.child.on("error", () => {
263	        this.initialized = false;
264	      });
265	
266	      this.child.on("exit", () => {
267	        this.initialized = false;
268	        this.failInFlight(new Error(`LSP server '${this.serverCmd}' exited`));
269	      });
270	      this.child.stdin?.on("error", () => {
271	        this.initialized = false;
272	      });
273	
274	      this.child.stdout?.on("data", (data: Buffer) => {
275	        this.handleData(data);
276	      });
277	
278	      const rootUri = pathToFileURL(this.rootPath).href;
279	
280	      // 1. Initialize
281	      const initRes = await this.sendRequest("initialize", {
282	        processId: process.pid,
283	        rootUri,
284	        capabilities: {
285	          textDocument: {
286	            hover: { contentFormat: ["markdown", "plaintext"] },
287	            definition: { dynamicRegistration: true },
288	            // Ask servers to attach document versions so delayed results for pre-edit content can be rejected.
289	            publishDiagnostics: { relatedInformation: true, versionSupport: true },
290	            synchronization: { didSave: true },
291	            // Pull diagnostics, except from a staged server: its lists come from several analyses and arrive by publish;
292	            // a pull would return one of them.
293	            ...(this.awaitProgress ? {} : { diagnostic: { dynamicRegistration: false, relatedDocumentSupport: false } }),
294	          },
295	          ...(this.awaitProgress ? {} : { workspace: { diagnostics: { refreshSupport: true } } }),
296	          // Declared so that servers which report progress (rust-analyzer) send $/progress, which diagnostics wait on.
297	          window: { workDoneProgress: true },
298	        },
299	      }, 5000);
300	
301	      if (!initRes) return false;
302	      const sync = initRes.capabilities?.textDocumentSync;
303	      if (typeof sync === "object" && sync?.save) {
304	        this.saveOptions = typeof sync.save === "object" ? sync.save : {};
305	      }
306	      const provider = initRes.capabilities?.diagnosticProvider;
307	      if (!this.awaitProgress && provider && typeof provider === "object") {
308	        this.diagnosticProvider = {
309	          ...(typeof provider.identifier === "string" ? { identifier: provider.identifier } : {}),
310	          interFileDependencies: provider.interFileDependencies === true,
311	          workspaceDiagnostics: provider.workspaceDiagnostics === true,
312	        };
313	      }
314	
315	      // 2. Initialized notification
316	      this.sendNotification("initialized", {});
317	      this.initialized = true;
318	      return true;
319	    } catch {
320	      this.initialized = false;
321	      return false;
322	    }
323	  }
324	
325	  /** Rejects every request still waiting and wakes every diagnostics waiter: the server is gone, so no answer is coming. */
326	  private failInFlight(err: Error): void {
327	    for (const { reject } of this.pending.values()) reject(err);
328	    this.pending.clear();
329	    const waiters = [...this.diagnosticWaiters.values()].flat();
330	    this.diagnosticWaiters.clear();
331	    for (const w of waiters) w();
332	  }
333	
334	  /** A server that sends more than the cap in one message, or buffers past it, is dropped rather than trusted with memory. */
335	  private dropOversized(): void {
336	    this.buffer = Buffer.alloc(0);
337	    this.initialized = false;
338	    this.failInFlight(new Error(`LSP server '${this.serverCmd}' exceeded the ${LSP_MAX_BUFFER_BYTES}-byte message limit`));
339	    try {
340	      this.child?.kill("SIGKILL");
341	    } catch {}
342	  }
343	
344	  private handleData(chunk: Buffer): void {
345	    this.buffer = Buffer.concat([this.buffer, chunk]);
346	
347	    while (true) {
348	      const headerEnd = this.buffer.indexOf("\r\n\r\n");
349	      if (headerEnd === -1) break;
350	
351	      const header = this.buffer.subarray(0, headerEnd).toString("latin1");
352	      const match = header.match(/Content-Length:\s*(\d+)/i);
353	      if (!match) {
354	        this.buffer = this.buffer.subarray(headerEnd + 4);
355	        continue;
356	      }
357	
358	      const contentLength = parseInt(match[1], 10);
359	      if (contentLength > LSP_MAX_BUFFER_BYTES) return this.dropOversized();
360	      const bodyStart = headerEnd + 4;
361	
362	      if (this.buffer.length < bodyStart + contentLength) {
363	        // Incomplete body, wait for next chunk
364	        break;
365	      }
366	
367	      const body = this.buffer.subarray(bodyStart, bodyStart + contentLength).toString("utf-8");
368	      this.buffer = this.buffer.subarray(bodyStart + contentLength);
369	
370	      try {
371	        const msg = JSON.parse(body);
372	        if (typeof msg.method === "string" && msg.id !== undefined) {
373	          // A request FROM the server (it has a method; its id space is its own, so it can collide with ours): answer it, or
374	          // a server that waits for the reply (window/workDoneProgress/create, workspace/configuration) can stall.
375	          this.answerServerRequest(msg);
376	          continue;
377	        }
378	        if (msg.method === "$/progress" && msg.params) {
379	          const token = String(msg.params.token);
380	          const kind = msg.params.value?.kind;
381	          if (kind === "begin") this.progressActive.set(token, this.seq);
382	          else if (kind === "end") {
383	            this.progressSettledSeq = Math.max(this.progressSettledSeq, this.progressActive.get(token) ?? 0);
384	            this.progressActive.delete(token);
385	          }
386	          this.progressSeen = true;
387	          this.lastProgressAt = Date.now();
388	          this.wake(ANY_DOCUMENT);
389	          continue;
390	        }
391	        if (msg.id !== undefined && this.pending.has(msg.id)) {
392	          const { resolve, reject } = this.pending.get(msg.id)!;
393	          this.pending.delete(msg.id);
394	          if (msg.error) {
395	            reject(Object.assign(new Error(msg.error.message || JSON.stringify(msg.error)), { code: msg.error.code, data: msg.error.data }));
396	          } else {
397	            resolve(msg.result);
398	          }
399	        } else if (msg.method === "textDocument/publishDiagnostics") {
400	          const params = msg.params;
401	          if (params && params.uri && Array.isArray(params.diagnostics)) {
402	            this.lastPublishAt = Date.now();
403	            this.wake(ANY_DOCUMENT);
404	            // A list is an answer only for a document the server holds from this client: one published for a file before
405	            // its first open, or after its close, describes content the client never sent and is not kept.
406	            const current = this.documentForUri(params.uri);
407	            if (!current) continue;
408	            if (typeof params.version === "number") {
409	              this.versionedPublishes = true;
410	              if (params.version !== current.version) continue; // published for an older version of the file than the server was last told about
411	            } else if (this.versionedPublishes) {
412	              // A server that attaches versions does so for every open document: once it has, a list without one is not
413	              // about a document as this client sent it (a "cleared" list after a close, arriving after the reopen).
414	              continue;
415	            }
416	            current.diagnostics = { list: toDiagnostics(params.diagnostics), seq: this.seq };
417	            this.wake(current.key);
418	          }
419	        }
420	      } catch {}
421	    }
422	    if (this.buffer.length > LSP_MAX_BUFFER_BYTES + 1024) this.dropOversized();
423	  }
424	
425	  public async sendRequest(method: string, params: any, timeoutMs: number = 8000): Promise<any> {
426	    if (!this.child || !this.child.stdin || this.child.killed || this.child.exitCode !== null) {
427	      throw new Error(`LSP server '${this.serverCmd}' is not running`);
428	    }
429	
430	    const id = this.nextId++;
431	    const payload = JSON.stringify({
432	      jsonrpc: "2.0",
433	      id,
434	      method,
435	      params,
436	    });
437	
438	    const header = `Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n`;
439	
440	    return new Promise((resolve, reject) => {
441	      const timer = setTimeout(() => {
442	        if (this.pending.has(id)) {
443	          this.pending.delete(id);
444	          reject(new Error(`LSP request '${method}' timed out after ${timeoutMs}ms`));
445	        }
446	      }, timeoutMs);
447	
448	      this.pending.set(id, {
449	        resolve: (val) => {
450	          clearTimeout(timer);
451	          resolve(val);
452	        },
453	        reject: (err) => {
454	          clearTimeout(timer);
455	          reject(err);
456	        },
457	      });
458	
459	      this.child!.stdin!.write(header + payload);
460	    });
461	  }
462	
463	  private answerServerRequest(msg: { id: number | string; method: string; params?: any }): void {
464	    if (!this.child || !this.child.stdin || this.child.killed || this.child.exitCode !== null) return;
465	    // The server's results changed for a reason the client did not cause: no kept report may stand in for a new one.
466	    if (msg.method === "workspace/diagnostic/refresh") for (const doc of this.documents.values()) doc.pulled = undefined;
467	    // Nothing is configured or registered on the server's behalf: an empty answer is a valid one for the requests servers send.
468	    const result = msg.method === "workspace/configuration" && Array.isArray(msg.params?.items) ? msg.params.items.map(() => null) : null;
469	    const payload = JSON.stringify({ jsonrpc: "2.0", id: msg.id, result });
470	    this.child.stdin.write(`Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n${payload}`);
471	  }
472	
473	  public sendNotification(method: string, params: any): void {
474	    if (!this.child || !this.child.stdin || this.child.killed || this.child.exitCode !== null) return;
475	    const payload = JSON.stringify({
476	      jsonrpc: "2.0",
477	      method,
478	      params,
479	    });
480	    const header = `Content-Length: ${Buffer.byteLength(payload, "utf-8")}\r\n\r\n`;
481	    this.child.stdin.write(header + payload);
482	  }
483	
484	  /**
485	   * The open document a server means by `uri`. Servers do not echo the client's spelling: they may publish under the real
486	   * path where the client sent a symlinked one, and percent-encode differently, so a URI that is not the one sent is
487	   * decoded to a path and compared with the two paths each document goes by. No file-system access.
488	   */
489	  private documentForUri(uri: unknown): OpenDocument | undefined {
490	    if (typeof uri !== "string") return undefined;
491	    const exact = this.opened.get(uri);
492	    if (exact) return exact;
493	    let named: string;
494	    try {
495	      named = comparablePath(fileURLToPath(uri));
496	    } catch {
497	      return undefined; // not a file URI
498	    }
499	    for (const doc of this.documents.values()) if (doc.paths.includes(named)) return doc;
500	    return undefined;
501	  }
502	
503	  private wake(key: string): void {
504	    const waiters = this.diagnosticWaiters.get(key);
505	    if (!waiters) return;
506	    this.diagnosticWaiters.delete(key);
507	    for (const w of waiters) w();
508	  }
509	
510	  private change(doc: OpenDocument, state: FileState): void {
511	    Object.assign(doc, state);
512	    doc.version = doc.changedSeq = this.lastChangeSeq = ++this.seq;
513	    doc.diagnostics = undefined;
514	    this.documentChangedAt.set(doc.key, Date.now());
515	    // Startup progress does not mean work for this newer document version has settled. A server may first
516	    // publish diagnostics for the updated version before its analysis has caught up; make the bounded grace
517	    // path apply again unless this edit produces fresh progress notifications.
518	    this.progressSeen = false;
519	    this.lastProgressAt = 0;
520	    this.sendNotification("textDocument/didChange", {
521	      textDocument: { uri: doc.uri, version: doc.version },
522	      contentChanges: [{ text: doc.text }],
523	    });
524	    if (this.saveOptions) {
525	      this.sendNotification("textDocument/didSave", {
526	        textDocument: { uri: doc.uri },
527	        ...(this.saveOptions.includeText ? { text: doc.text } : {}),
528	      });
529	    }
530	  }
531	
532	  /** `gone`: the file is no longer there for the server to read, which changes what other files' answers are computed from. */
533	  private close(doc: OpenDocument, gone: boolean): void {
534	    this.documents.delete(doc.key);
535	    this.opened.delete(doc.uri);
536	    this.documentChangedAt.delete(doc.key);
537	    if (gone) this.unevidencedSeq = this.lastChangeSeq = ++this.seq;
538	    else if (!doc.diagnostics) this.unevidencedSeq = Math.max(this.unevidencedSeq, doc.changedSeq);
539	    this.sendNotification("textDocument/didClose", { textDocument: { uri: doc.uri } });
540	    this.wake(doc.key);
541	    this.wake(ANY_DOCUMENT);
542	  }
543	
544	  /**
545	   * Makes every open document match the disk: a file whose content moved gets a full-text didChange (and didSave where
546	   * the server asked for it); one that is gone, is no longer a regular file, or no longer resolves to itself inside the
547	   * workspace (renamed, or replaced by a symlink) is closed without being read.
548	   * Per document: one realpath and one stat; the content is read only when the stamp moved or cannot be trusted yet.
549	   */
550	  private resync(realRoot: string | null): void {
551	    for (const doc of [...this.documents.values()]) {
552	      let state: FileState | null = null;
553	      if (realRoot !== null && realOrNull(doc.key) === doc.key && !outsideRoot(realRoot, doc.key)) {
554	        try {
555	          const st = fs.statSync(doc.key, { bigint: true });
556	          if (doc.settled && stampOf(st, 0).stamp === doc.stamp) continue;
557	          if (st.isFile()) state = readRegularFile(doc.key);
558	        } catch {}
559	      }
560	      if (!state) this.close(doc, true);
561	      else if (state.text !== doc.text) this.change(doc, state);
562	      else Object.assign(doc, state);
563	    }
564	  }
565	
566	  /**
567	   * The one way a query reaches a file: brings every open document up to date with the disk, then opens `filePath` if
568	   * the server does not hold it yet and closes the least recently queried documents beyond the bound.
569	   * Throws when the file cannot be read or lies outside the workspace.
570	   */
571	  private open(filePath: string, languageId: string): OpenDocument {
572	    // Resolve symlinks before the containment check: a link inside the workspace must not read a file outside it.
573	    const realRoot = realOrNull(this.rootPath);
574	    this.resync(realRoot);
575	    const key = realRoot === null ? null : realOrNull(path.resolve(this.rootPath, filePath));
576	    if (realRoot === null || key === null || outsideRoot(realRoot, key)) throw unreadable(filePath);
577	    let doc = this.documents.get(key);
578	    if (doc) {
579	      this.documents.delete(key);
580	    } else {
581	      const state = readRegularFile(key);
582	      if (!state) throw unreadable(filePath);
583	      // Named as the workspace was given to the server (its rootUri), so a server that relates documents to the root by
584	      // prefix finds them inside it; below the root the real path, so one file has one name.
585	      const sent = path.join(this.rootPath, path.relative(realRoot, key));
586	      doc = { ...state, key, uri: pathToFileURL(sent).href, paths: [comparablePath(sent), comparablePath(key)], version: ++this.seq, changedSeq: 0, waiting: 0 };
587	      this.opened.set(doc.uri, doc);
588	      this.sendNotification("textDocument/didOpen", { textDocument: { uri: doc.uri, languageId, version: doc.version, text: doc.text } });
589	    }
590	    this.documents.set(key, doc);
591	    for (const old of this.documents.values()) {
592	      if (this.documents.size <= MAX_OPEN_DOCUMENTS) break;
593	      // What the server held was just checked against the disk, so closing it changes nothing the server computes from.
594	      if (old !== doc && old.waiting === 0) this.close(old, false);
595	    }
596	    return doc;
597	  }
598	
599	  /**
600	   * Push-only servers: when a list that arrived at `listSeq`, before a later change to another document, may be taken as
601	   * still current, or null while nothing shows that the server has dealt with that change. Silence is not evidence:
602	   *  - a staged server: a progress cycle that began after the latest change has ended, nothing is in progress, and
603	   *    progress has been quiet for QUIET_MS;
604	   *  - any other server: it has published for every document changed since the list arrived (that publish shows it
605	   *    analysed the change), and has published nothing for PUBLISH_QUIET_MS.
606	   * Known limit: a server that publishes for the changed document, stays silent for longer than the window, and only
607	   * then publishes a different list for this document has its old list returned as current once. A server that offers
608	   * pull diagnostics is asked instead and has no such window.
609	   */
610	  private settledAt(listSeq: number): number | null {
611	    if (this.awaitProgress) {
612	      return this.progressSettledSeq >= this.lastChangeSeq && this.progressActive.size === 0 ? this.lastProgressAt + QUIET_MS : null;
613	    }
614	    if (this.unevidencedSeq > listSeq) return null;
615	    for (const doc of this.documents.values()) if (doc.changedSeq > listSeq && !doc.diagnostics) return null;
616	    return this.lastPublishAt + PUBLISH_QUIET_MS;
617	  }
618	
619	  /**
620	   * The diagnostics for the file as it is on disk now, or why there are none to report.
621	   * From a server that offers pull diagnostics: its reply to a request made after the sync.
622	   * Otherwise from what it published: a list counts when it arrived after the latest change the client had sent when
623	   * this call began (and, where the server attaches versions, for this document's version), or when it is older than a
624	   * change to another document and `settledAt` says the server has dealt with that change. Throws for an unreadable file.
625	   */
626	  public async waitForDiagnostics(filePath: string, languageId: string, timeoutMs: number): Promise<DiagnosticsAnswer> {
627	    const doc = this.open(filePath, languageId);
628	    if (this.diagnosticProvider) return this.pullDiagnostics(doc, filePath, timeoutMs, this.diagnosticProvider.identifier);
629	    const key = doc.key;
630	    const since = this.lastChangeSeq;
631	    const held = () => this.documents.get(key)?.diagnostics;
632	    const current = (): LspDiagnostic[] | null => {
633	      const d = held();
634	      return d && d.seq >= since ? d.list : null;
635	    };
636	    const stands = (now: number): LspDiagnostic[] | null => {
637	      const d = held();
638	      const at = d ? this.settledAt(d.seq) : null;
639	      return d && at !== null && now >= at ? d.list : null;
640	    };
641	    const startedAt = Date.now();
642	    const changedAt = this.documentChangedAt.get(key);
643	    doc.waiting++;
644	    try {
645	      // A staged server's first publish may be empty. Wait until its progress has ended and been quiet for a moment (or, if it
646	      // never reports progress, for a grace period), within the caller's timeout, then return the latest list.
647	      const GRACE_MS = 4000;
648	      for (let now = startedAt; now - startedAt < timeoutMs; now = Date.now()) {
649	        if (!current()) {
650	          if (stands(now)) break;
651	          // No list: wait for one. A list from before another document's change: wait for the server to publish or end
652	          // progress, or for the moment its quiet period is over.
653	          const d = held();
654	          const at = d ? this.settledAt(d.seq) : null;
655	          const left = timeoutMs - (now - startedAt);
656	          await this.nextPublish(d ? ANY_DOCUMENT : key, at === null ? left : Math.min(left, Math.max(1, at - now)));
657	          if (!this.documents.has(key) || !this.initialized) break; // closed, or the server is gone
658	          continue;
659	        }
660	        if (!this.awaitProgress) break;
661	        const idle = this.progressActive.size === 0;
662	        const settled = this.progressSeen ? now - this.lastProgressAt >= QUIET_MS : now - startedAt >= GRACE_MS;
663	        const editSettled = changedAt === undefined || now - changedAt >= EDIT_DIAGNOSTICS_GRACE_MS;
664	        if (idle && settled && editSettled) break;
665	        await new Promise((r) => setTimeout(r, 100));
666	      }
667	      if (this.awaitProgress && changedAt !== undefined && Date.now() - changedAt >= EDIT_DIAGNOSTICS_GRACE_MS) this.documentChangedAt.delete(key);
668	      const diagnostics = current() ?? stands(Date.now());
669	      if (diagnostics) return { status: "ok", diagnostics };
670	      const what = held() ? `for ${filePath} after another open file changed,` : `for ${filePath}`;
671	      return { status: "unavailable", reason: `Language server '${this.serverCmd}' published no diagnostics ${what} within ${timeoutMs}ms.` };
672	    } finally {
673	      doc.waiting--;
674	    }
675	  }
676	
677	  /**
678	   * One `textDocument/diagnostic` exchange. A full report is the answer and is kept with its `resultId`; "unchanged" is
679	   * an answer only for the kept list that `resultId` was sent for. Reports for related documents are not used. Asked
680	   * again when the server cancels with `retriggerRequest`, a bounded number of times within the timeout.
681	   */
682	  private async pullDiagnostics(doc: OpenDocument, filePath: string, timeoutMs: number, identifier?: string): Promise<DiagnosticsAnswer> {
683	    const deadline = Date.now() + timeoutMs;
684	    const unavailable = (why: string): DiagnosticsAnswer => ({ status: "unavailable", reason: `Language server '${this.serverCmd}' gave no diagnostics for ${filePath}: ${why}` });
685	    for (let attempt = 0; ; attempt++) {
686	      const previousResultId = doc.pulled?.resultId;
687	      let report: any;
688	      try {
689	        report = await this.sendRequest(
690	          "textDocument/diagnostic",
691	          { textDocument: { uri: doc.uri }, ...(identifier !== undefined ? { identifier } : {}), ...(previousResultId !== undefined ? { previousResultId } : {}) },
692	          Math.max(1, deadline - Date.now()),
693	        );
694	      } catch (err: any) {
695	        if (err.code === SERVER_CANCELLED && err.data?.retriggerRequest === true && attempt < PULL_RETRIGGER_LIMIT && Date.now() < deadline) continue;
696	        return unavailable(`${err.message}.`);
697	      }
698	      if (report?.kind === "full" && Array.isArray(report.items)) {
699	        doc.pulled = { list: toDiagnostics(report.items), ...(typeof report.resultId === "string" ? { resultId: report.resultId } : {}) };
700	        return { status: "ok", diagnostics: doc.pulled.list };
701	      }
702	      if (report?.kind === "unchanged" && previousResultId !== undefined) {
703	        if (doc.pulled) {
704	          if (typeof report.resultId === "string") doc.pulled.resultId = report.resultId;
705	          return { status: "ok", diagnostics: doc.pulled.list };
706	        }
707	        // The kept list was dropped while the request was out (workspace/diagnostic/refresh): ask for a full report.
708	        if (attempt < PULL_RETRIGGER_LIMIT && Date.now() < deadline) continue;
709	      }
710	      return unavailable("its report was neither a full list nor 'unchanged' for a list this client holds.");
711	    }
712	  }
713	
714	  /** Resolves when a list is accepted for the document, when it is closed, when the server is gone, or at the timeout. */
715	  private nextPublish(key: string, timeoutMs: number): Promise<void> {
716	    return new Promise<void>((resolve) => {
717	      const timer = setTimeout(() => {
718	        const list = this.diagnosticWaiters.get(key)?.filter((w) => w !== done) ?? [];
719	        if (list.length) this.diagnosticWaiters.set(key, list);
720	        else this.diagnosticWaiters.delete(key);
721	        resolve();
722	      }, timeoutMs);
723	      const done = () => {
724	        clearTimeout(timer);
725	        resolve();
726	      };
727	      this.diagnosticWaiters.set(key, [...(this.diagnosticWaiters.get(key) ?? []), done]);
728	    });
729	  }
730	
731	  public pid(): number | undefined {
732	    return this.child?.pid;
733	  }
734	
735	  public async getHover(filePath: string, languageId: string, line: number, character: number): Promise<string | null> {
736	    const { uri } = this.open(filePath, languageId);
737	    const res = await this.sendRequest("textDocument/hover", {
738	      textDocument: { uri },
739	      position: { line: Math.max(0, line - 1), character: Math.max(0, character - 1) },
740	    });
741	
742	    if (!res || !res.contents) return null;
743	
744	    if (typeof res.contents === "string") return res.contents;
745	    if (res.contents.value) return res.contents.value;
746	    if (Array.isArray(res.contents)) {
747	      return res.contents.map((c: any) => (typeof c === "string" ? c : c.value || "")).join("\n\n");
748	    }
749	    return JSON.stringify(res.contents);
750	  }
751	
752	  public async getDefinition(filePath: string, languageId: string, line: number, character: number): Promise<LspLocation[] | null> {
753	    const { uri } = this.open(filePath, languageId);
754	    const res = await this.sendRequest("textDocument/definition", {
755	      textDocument: { uri },
756	      position: { line: Math.max(0, line - 1), character: Math.max(0, character - 1) },
757	    });
758	
759	    if (!res) return null;
760	    if (Array.isArray(res)) return res;
761	    if (res.uri && res.range) return [res];
762	    return null;
763	  }
764	
765	  public shutdown(): void {
766	    if (this.child) {
767	      try {
768	        this.sendRequest("shutdown", {}).catch(() => {});
769	        this.sendNotification("exit", {});
770	        this.child.kill("SIGTERM");
771	      } catch {}
772	      this.child = null;
773	    }
774	    this.initialized = false;
775	  }
776	}
