778	/**
779	 * Manager to auto-route LSP queries based on file extension
780	 */
781	export class LspBridgeManager {
782	  private static live: Set<LspBridgeManager> = new Set();
783	  private static exitHookInstalled = false;
784	
785	  private workspace: string;
786	  private clients: Map<string, LspClient> = new Map();
787	  private starting: Map<string, Promise<LspClient | null>> = new Map();
788	  private closed = false;
789	  private servers: Record<string, LspServerSpec>;
790	  private gate?: () => string | null;
791	
792	  /** `gate` returns the reason a server must not start right now (untrusted workspace, sandbox), or null to allow it. */
793	  constructor(workspace: string, opts: { servers?: Record<string, LspServerSpec>; gate?: () => string | null } = {}) {
794	    this.workspace = path.resolve(workspace);
795	    this.gate = opts.gate;
796	    this.servers = opts.servers ?? {};
797	    LspBridgeManager.live.add(this);
798	    if (!LspBridgeManager.exitHookInstalled) {
799	      LspBridgeManager.exitHookInstalled = true;
800	      // Backstop: a language server must never outlive the process, even if no owner called shutdownAll.
801	      process.on("exit", () => {
802	        for (const m of LspBridgeManager.live) m.shutdownAll();
803	      });
804	    }
805	  }
806	
807	  /** The gate's refusal, if any. A refusal also stops servers that started while the workspace was still allowed. */
808	  private refusal(): string | null {
809	    const reason = this.gate?.() ?? null;
810	    if (reason) {
811	      for (const client of this.clients.values()) client.shutdown();
812	      this.clients.clear();
813	    }
814	    return reason;
815	  }
816	
817	  public getServerForFile(filePath: string): LspServerSpec | null {
818	    const ext = path.extname(filePath).toLowerCase();
819	    if (this.servers[ext]) return this.servers[ext];
820	    if (ext === ".rs") {
821	      return { cmd: "rust-analyzer", languageId: "rust", awaitProgress: true };
822	    }
823	    if (ext === ".ts" || ext === ".tsx") {
824	      return { cmd: "typescript-language-server", args: ["--stdio"], languageId: "typescript" };
825	    }
826	    if (ext === ".js" || ext === ".jsx") {
827	      return { cmd: "typescript-language-server", args: ["--stdio"], languageId: "javascript" };
828	    }
829	    if (ext === ".py") {
830	      return { cmd: "pyright-langserver", args: ["--stdio"], languageId: "python" };
831	    }
832	    if (ext === ".go") {
833	      return { cmd: "gopls", languageId: "go" };
834	    }
835	    return null;
836	  }
837	
838	  public async getClientForFile(filePath: string): Promise<LspClient | null> {
839	    const serverInfo = this.getServerForFile(filePath);
840	    if (!serverInfo || this.refusal()) return null;
841	    this.closed = false;
842	    LspBridgeManager.live.add(this);
843	    const key = `${serverInfo.cmd}\0${(serverInfo.args ?? []).join("\0")}`;
844	
845	    const existing = this.clients.get(key);
846	    if (existing?.initialized) return existing;
847	    const inFlight = this.starting.get(key);
848	    if (inFlight) return inFlight;
849	
850	    const startup = (async () => {
851	      const client = new LspClient(serverInfo.cmd, this.workspace, serverInfo.args ?? [], serverInfo.env, serverInfo.awaitProgress === true);
852	      const ok = await client.start();
853	      if (ok && this.closed) {
854	        client.shutdown();
855	        return null;
856	      }
857	      if (ok) {
858	        this.clients.set(key, client);
859	        return client;
860	      }
861	      client.shutdown();
862	      return null;
863	    })().finally(() => this.starting.delete(key));
864	    this.starting.set(key, startup);
865	    return startup;
866	  }
867	
868	  /**
869	   * Diagnostics for one file. "ok" means the server published for this file's current content (an empty list is then a
870	   * real "no errors"); "unavailable" means no answer, which callers must not read as a clean file.
871	   */
872	  public async diagnostics(
873	    filePath: string,
874	    timeoutMs: number = 5000,
875	  ): Promise<DiagnosticsAnswer> {
876	    const info = this.getServerForFile(filePath);
877	    if (!info) return { status: "unavailable", reason: `No LSP server configured for ${filePath}.` };
878	    const refused = this.refusal();
879	    if (refused) return { status: "unavailable", reason: refused };
880	    const client = await this.getClientForFile(filePath);
881	    if (!client) return { status: "unavailable", reason: `Language server '${info.cmd}' is not installed or failed to start.` };
882	    try {
883	      return await client.waitForDiagnostics(filePath, info.languageId, timeoutMs);
884	    } catch (err: any) {
885	      return { status: "unavailable", reason: err.message };
886	    }
887	  }
888	
889	  public serverPids(): number[] {
890	    return [...this.clients.values()].map((c) => c.pid()).filter((p): p is number => typeof p === "number");
891	  }
892	
893	  public async hover(filePath: string, line: number, character: number): Promise<{ found: boolean; hoverText?: string; error?: string }> {
894	    const refused = this.getServerForFile(filePath) ? this.refusal() : null;
895	    if (refused) return { found: false, error: refused };
896	    const client = await this.getClientForFile(filePath);
897	    if (!client) {
898	      const info = this.getServerForFile(filePath);
899	      return {
900	        found: false,
901	        error: info ? `Language server '${info.cmd}' is not installed or failed to start.` : `No LSP server configured for ${filePath}.`,
902	      };
903	    }
904	
905	    try {
906	      const text = await client.getHover(filePath, this.getServerForFile(filePath)!.languageId, line, character);
907	      return { found: Boolean(text), hoverText: text || "No hover documentation available." };
908	    } catch (err: any) {
909	      return { found: false, error: err.message };
910	    }
911	  }
912	
913	  public async definition(filePath: string, line: number, character: number): Promise<{ found: boolean; locations?: LspLocation[]; error?: string }> {
914	    const refused = this.getServerForFile(filePath) ? this.refusal() : null;
915	    if (refused) return { found: false, error: refused };
916	    const client = await this.getClientForFile(filePath);
917	    if (!client) {
918	      const info = this.getServerForFile(filePath);
919	      return {
920	        found: false,
921	        error: info ? `Language server '${info.cmd}' is not installed or failed to start.` : `No LSP server configured for ${filePath}.`,
922	      };
923	    }
924	
925	    try {
926	      const locations = await client.getDefinition(filePath, this.getServerForFile(filePath)!.languageId, line, character);
927	      return { found: Boolean(locations && locations.length > 0), locations: locations || [] };
928	    } catch (err: any) {
929	      return { found: false, error: err.message };
930	    }
931	  }
932	
933	  public shutdownAll(): void {
934	    this.closed = true;
935	    for (const client of this.clients.values()) {
936	      client.shutdown();
937	    }
938	    this.clients.clear();
939	    LspBridgeManager.live.delete(this);
940	  }
941	}
