  fs.mkdirSync(ws);
  const mgr = new LspBridgeManager(ws, { gate: () => null }); // the product's server table and timings
  try {
    await withPath(empty, async () => {
      for (const [file, cmd, hint] of [
        ["a.rs", "rust-analyzer", "rustup component add rust-analyzer"],
